pragma solidity >=0.8.0;
contract EventOrderPack {
    event Mark(uint8 indexed tag, string indexed s, bytes b);
    uint8 public flag;
    string public s2;
    bytes public b1;
    string public s1;
    function mix() external {
        flag = 255;
        s1 = "a";
        b1 = hex"00";
        emit Mark(255, s1, b1);
        s2 = "bc";
        b1 = hex"";
        emit Mark(2, s2, b1);
    }
    function getAll() external view returns (uint8, string memory, bytes memory, string memory) {
        return (flag, s1, b1, s2);
    }
}
